        r=urllib.request.urlopen(urllib.request.Request(u,method="HEAD")); print(m,"HEAD",r.status,"bytes=",r.headers.get("Content-Length"))
    except Exception as e: print(m,"HEAD ERR",e)' > /tmp/head.txt 2>&1

